use std::fs::File;
use std::io::{self, Read};

fn carrega_nome(path: &str) -> Result<String, io::Error> {
    let mut arquivo = File::open(path)?;
    let mut nome = String::new();
    arquivo.read_to_string(&mut nome)?;
    let copia = nome;
    println!("{}", nome);
    Ok(copia)
}
